Lemma lor_bit_bound : forall a w k, 0 <= a <= 1 -> 0 <= k -> 0 <= w < 2^k -> 0 <= Z.lor a (w * 2) < 2^(k+1).
Proof.
  intros a w k Ha Hk Hw.
  assert (P1 : 1 <= 2^k) by (pose proof (Z.pow_le_mono_r 2 0 k ltac:(lia) Hk); lia).
  assert (E2 : 2^(k+1) = 2^k * 2) by (rewrite Z.pow_add_r by lia; reflexivity).
  pose proof (lor_lt_pow2 a (w * 2) (k + 1) ltac:(lia) ltac:(lia)). lia.
Qed.
