    Lemma lookup_walk : forall (window k RBB limb bit : Z) (mm : mem) (xs tab sel tmp : list word)
        (xra xt0 xt1 xt2 xt3 xt4 xt5 xt6 xa0 xa1 xa2 xa3 xa4 xa5 xa6 xa7 ys8 ys10 wlb w4an wnxs : word),
      0 <= k <= ws -> 0 <= window < 2 ^ k -> 0 <= bit <= 31 -> 0 <= limb < en -> 32 * limb + bit <= RBB -> KBODY RBB ->
