      assert (AW : 0 <= an * window /\ an * window + an <= wa).
      { split; [apply Z.mul_nonneg_nonneg; clear -Han Hw8; lia|]. rewrite (unlock _ HWA), (Z.mul_comm welem an), <- Z.mul_succ_r.
        apply Z.mul_le_mono_nonneg_l; clear -Han Hw8; lia. }
      pose proof MV as MV0. flat constr:(MV) 13%nat. flclear MV. intros HX LX HT LTB HS LS HM LM HL MU WM MI ST.
