      match goal with |- context [Z.shiftr (an * window + ?c) 62] =>
        assert (H62 : Z.shiftr (an * window + c) 62 = 0)
          by (rewrite Z.shiftr_div_pow2 by lia; apply Z.div_small; try change (2^62) with 4611686018427387904; clear -AW HW2 Han; lia);
        rewrite H62 end.
