      rewrite <- (firstn_skipn (Z.to_nat an) (skipn (Z.to_nat (an * window)) tab)) in HSRC.
      rewrite u32s_app in HSRC. apply bytes_at_app in HSRC. flat constr:(HSRC) 2%nat. flclear HSRC. intros HSRC _.
      pose proof (u32arr_cells _ _ _ _ HS) as HD.
      pose proof U_memcpy_spec as SP. unfold memcpy_stmt in SP.
