        all: first [ exact MI
                   | (match goal with |- bytes_at _ _ ?a _ => replace a with (T + 4 * Z.of_nat (Z.to_nat (an * window))) by (clear -AW; lia); exact HSRC end)
                   | (match goal with |- rw_cells _ _ _ [CB ?n _] => replace n with (4 * length sel)%nat by (clear -LS Han; lia); exact HD end)
                   | (rewrite ?u32s_length, ?firstn_length, ?skipn_length; clear -AW LTB Han; lia)
                   | (rewrite EXS; clear -AW Han HW2 HWL; lia)
                   | klia ]. }
      clear SP HSRC HD. unfold memcpy_post. rewrite ?unsigned_lit by klia.
      post_call usegs mmc.
      match goal with H : rw_cells usegs ?m2 XS [CB _ (u32s ?ws)] |- _ =>
        apply (u32arr_of_cells usegs m2 _ _ _ ws) in H; [| reflexivity]; rename H into HS2;
        assert (LS2 : Z.of_nat (length ws) = an) by (rewrite firstn_length, skipn_length; clear -AW LTB Han; lia) end.
      lx_mkR.
      lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?m2 _) =>
        lazymatch type of HS2 with u32arr _ _ _ ?sel2 =>
        lazymatch goal with H6 : mem_inv usegs m2, H7 : stk usegs m2 lo _, FR' : rw_cells usegs m2 (bv_unsigned sp + -208) _ |- _ =>
          eapply (mult_walk RBB limb bit m2 xs tab sel2 tmp); [exact Hbit | exact Hlimb | exact HRB | exact KB | | exact FR' | exact Ewlb | reflexivity | reflexivity];
          refine (conj _ (conj LX (conj _ (conj LTB (conj HS2 (conj LS2 (conj _ (conj LM (conj _ (conj _ (conj _ (conj H6 H7)))))))))))) end end end.
      all: assumption.
    Qed.
