    Lemma body_walk : forall kk : nat, KBODY (Z.of_nat kk).
    Proof using All.
      induction kk as [|kk IH]; unfold KBODY; intros limb bit wbits window mm xs tab sel tmp xra xt0 xt1 xt2 xa0 xa1 xa2 xa3 xa4 xa5 xa6 xa7 ys9 ys11 xt3 xt4 xt5 xt6 w4an wnxs wsel NU Hrem MV FR -> -> ->.
      { exfalso. flat constr:(NU) 5%nat. flclear NU. intros Hb Hl _ H1 _. clear -Hb Hl H1 Hrem. lia. }
      pose proof MV as MV0. flat constr:(MV) 13%nat. flclear MV. intros HX LX HT LTB HS LS HM LM HL MU WM MI ST.
      flat constr:(NU) 6%nat. flclear NU. intros Hbit Hlimb Hle Hrem1 Hwb Hwin.
      assert (PW : 2 ^ wbits <= 4) by (change 4 with (2^2); apply Z.pow_le_mono_r; clear -Hwb HWS; lia).
      assert (Hwin4 : window < 4) by (clear -Hwin PW; lia).
      pose proof (u32ro_transport _ _ _ _ _ _ HN0 MU ltac:(cbn [disjoint_from]; rewrite LN; destruct (unlock _ DNX), (unlock _ DNT), (unlock _ SN); clear -Han Ln LO H H0 H1; lia)) as HN.
      pose proof (u32ro_transport _ _ _ _ _ _ HE0 MU ltac:(cbn [disjoint_from]; rewrite LE; destruct (unlock _ DEX), (unlock _ DET), (unlock _ SE); clear -Han Hen Ln LO H H0 H1; lia)) as HE.
      pose proof (unlock _ DNT) as DNT'. pose proof (unlock _ DNX) as DNX'. pose proof (unlock _ SN) as SN'.
      pose proof (unlock _ DET) as DET'. pose proof (unlock _ DEX) as DEX'. pose proof (unlock _ SE) as SE'.
      lx_hide MU. lx_hide WM. lx_hide IH. lx_hide MV0. lx_hide PW. lx_hide Hwin.
      pose proof (sumsxm_sq_ok GSL) as LXSUMS.
      lx_run_tac (PLANS [0x2492c; 0x249d0] [] 80%N SUMSXM_SQ); lx_tree.
      (* [comment removed for export] *)
      all: repeat match goal with H : (if _ then false else true) = true |- _ => apply lxp_if_negb in H end; lf_zlow_by Hbit Hlimb Hwb.
      all: let xwb := constr:(wbits) in let xkk := constr:(kk) in
           lazymatch goal with
           | |- evt _ _ (MS _ _ (ret_pc _) _ _ _ _) => lf_fin
           | |- evt _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (Z_to_bv 64 (Z.lor (Z.land ?eb 1) (2 * ?w0))) _ _ _ (Z_to_bv 64 ?limb') _ _ (Z_to_bv 64 ?b9) (Z_to_bv 64 ?b10) _ _ _ _ _) _ (Z_to_bv 64 ?pc) _ _ _ _) =>
               lf_minv; lx_unhide;
               let B1 := fresh "B1" in let WB := fresh "WB" in
               pose proof (land_1_range eb) as B1;
               lazymatch goal with Hwb : 0 <= xwb < _, Hwin : 0 <= w0 < _ |- _ =>
                 pose proof (lor_bit_bound2 _ w0 xwb B1 ltac:(clear -Hwb; lia) Hwin) as WB end;
               lazymatch goal with FR' : rw_cells _ _ (bv_unsigned sp + -208) _, IH : KBODY (Z.of_nat xkk) |- _ =>
               lazymatch pc with
               | 149968 =>
                   eapply (lookup_walk _ (xwb + 1) (Z.of_nat xkk) limb' b9);
                   [ klia | exact WB | klia | klia | klia | exact IH | eassumption | exact FR' | reflexivity | reflexivity | reflexivity ]
               | 149804 =>
                   first [ match goal with K : (zlow 64 (Z.lor limb' b10) =? 0) = false |- _ =>
                             pose proof (lxp_lor_flag0 limb' b10 ltac:(klia) ltac:(klia) (proj2 (lor_lt_pow2 limb' b10 64 ltac:(klia) ltac:(klia))) K) as NZ end
                         | match goal with K : (zlow 64 (Z.lor limb' b10) =? zlow 64 0) = false |- _ =>
                             pose proof (lxp_lor_flag limb' b10 ltac:(klia) ltac:(klia) (proj2 (lor_lt_pow2 limb' b10 64 ltac:(klia) ltac:(klia))) K) as NZ end ];
                   eapply (IH limb' b10 (xwb + 1));
                   [ unfold NUMSL; (flsplit; repeat split); try exact WB; klia | klia | eassumption | exact FR' | reflexivity | reflexivity | reflexivity ]
               end end
           end.
    Qed.
