  Notation FRAMEB mm j1 j2 j3 := (rw_cells usegs mm (bv_unsigned sp + -208)
       [CB 32 j1; C8 (Z_to_bv 64 EP); CB 32 j2; C8 (Z_to_bv 64 X); CB 24 j3;
        C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).

  (* [comment removed for export] *)
  Ltac phaseB2_case :=
    lazymatch goal with HT : u32arr _ ?mm T ts0, HWA : ?wa = _ * an |- _ =>
    (* [comment removed for export] *)
    (flat constr:((u32arr_take _ _ _ _ (Z.to_nat wa) HT ltac:(klia))) 2%nat; intros HTAB HR1);
    destruct (u32arr_take _ _ _ _ (Z.to_nat an) HR1 ltac:(rewrite skipn_length; klia)) as [HS HR2]; clear HR1;
    destruct (u32arr_take _ _ _ _ (Z.to_nat (2 * an + 1)) HR2 ltac:(rewrite !skipn_length; klia)) as [HM HL]; clear HR2;
    rewrite !skipn_skipn in HL; rewrite skipn_skipn in HM;
    replace (T + 4 * Z.of_nat (Z.to_nat wa)) with (T + 4 * wa) in HS, HM, HL by klia;
    replace (T + 4 * wa + 4 * Z.of_nat (Z.to_nat an)) with (T + 4 * (wa + an)) in HM, HL by klia;
    replace (T + 4 * (wa + an) + 4 * Z.of_nat (Z.to_nat (2 * an + 1))) with (T + 4 * (wa + an + (2 * an + 1))) in HL by klia;
    let tab0 := fresh "tab0" in let sel0 := fresh "sel0" in let tmp0 := fresh "tmp0" in let tl := fresh "tl" in
    lazymatch type of HTAB with u32arr _ _ _ ?l => set (tab0 := l) in HTAB end;
    lazymatch type of HS with u32arr _ _ _ ?l => set (sel0 := l) in HS end;
    lazymatch type of HM with u32arr _ _ _ ?l => set (tmp0 := l) in HM end;
    lazymatch type of HL with u32arr _ _ _ ?l => set (tl := l) in HL end;
    assert (LTB : Z.of_nat (length tab0) = wa) by (subst tab0; rewrite firstn_length; klia);
    assert (LS : Z.of_nat (length sel0) = an) by (subst sel0; rewrite firstn_length, skipn_length; klia);
    assert (LM : Z.of_nat (length tmp0) = 2 * an + 1) by (subst tmp0; rewrite firstn_length, skipn_length; klia);
    assert (LTL : Z.of_nat (length tl) = lt - (wa + an + (2 * an + 1))) by (subst tl; rewrite skipn_length; klia);
    clearbody tab0 sel0 tmp0 tl; clear HT;
    (* [comment removed for export] *)
    assert (ALS : (T + 4 * wa) mod 4 = 0) by (clear -ALT; lia);
    assert (ALM : (T + 4 * (wa + an)) mod 4 = 0) by (clear -ALT; lia);
    let XS := fresh "XS" in let XM := fresh "XM" in let XL := fresh "XL" in
    remember (T + 4 * wa) as XS eqn:EXS in HS, ALS;
    remember (T + 4 * (wa + an)) as XM eqn:EXM in HM, ALM;
